import EarningsChart from '../../components/vendor/EarningsChart';
import { useVendorEarningsQuery } from '../../store/api/vendorApi';
export default function VendorEarnings(){const{data}=useVendorEarningsQuery();const rows=data?.rows||[];return <main className="mx-auto max-w-7xl px-4 py-10"><h1 className="font-heading text-5xl text-navy">Earnings</h1><div className="mt-6 grid gap-4 md:grid-cols-3"><div className="card p-5"><p>Total earned</p><b className="text-3xl text-navy">₹{data?.total||0}</b></div><div className="card p-5"><p>Pending</p><b className="text-3xl text-gold">₹0</b></div><div className="card p-5"><p>Commission deducted</p><b className="text-3xl text-navy">10%</b></div></div><div className="card mt-6 p-5"><EarningsChart type="bar" /></div><div className="card mt-6 overflow-x-auto p-5"><table className="w-full text-left"><thead><tr><th>Order</th><th>Date</th><th>Amount</th><th>Commission</th><th>Net</th></tr></thead><tbody>{rows.map(r=><tr className="border-t" key={r.orderNumber}><td>{r.orderNumber}</td><td>{new Date(r.date).toLocaleDateString()}</td><td>₹{r.amount}</td><td>₹{r.commission}</td><td>₹{r.net}</td></tr>)}</tbody></table></div></main>}
